ALTER TABLE "status_pipeline_nodes" ADD COLUMN "hue" text DEFAULT 'gray' NOT NULL;--> statement-breakpoint
UPDATE "status_pipeline_nodes" SET "hue" = CASE "slug" WHEN 'lead' THEN 'slate' WHEN 'scheduled' THEN 'blue' WHEN 'assessed' THEN 'indigo' WHEN 'quoted' THEN 'violet' WHEN 'accepted' THEN 'teal' WHEN 'in_progress' THEN 'amber' WHEN 'completed' THEN 'green' WHEN 'deliverable_pending' THEN 'orange' WHEN 'deliverable_complete' THEN 'green' WHEN 'invoiced' THEN 'blue' WHEN 'paid' THEN 'green' WHEN 'on_hold' THEN 'slate' WHEN 'cancelled' THEN 'slate' WHEN 'draft' THEN 'slate' WHEN 'sent' THEN 'blue' WHEN 'rejected' THEN 'red' WHEN 'expired' THEN 'gray' WHEN 'partial' THEN 'amber' WHEN 'voided' THEN 'gray' WHEN 'generating' THEN 'amber' WHEN 'ready' THEN 'green' WHEN 'failed' THEN 'red' WHEN 'queued' THEN 'slate' WHEN 'running' THEN 'amber' WHEN 'succeeded' THEN 'green' END WHERE "slug" IN ('lead', 'scheduled', 'assessed', 'quoted', 'accepted', 'in_progress', 'completed', 'deliverable_pending', 'deliverable_complete', 'invoiced', 'paid', 'on_hold', 'cancelled', 'draft', 'sent', 'rejected', 'expired', 'partial', 'voided', 'generating', 'ready', 'failed', 'queued', 'running', 'succeeded');--> statement-breakpoint
UPDATE "status_pipeline_nodes" AS n SET "hue" = (SELECT h.hue FROM (VALUES ('slate', 71, 85, 105), ('blue', 37, 99, 235), ('indigo', 79, 70, 229), ('violet', 124, 58, 237), ('teal', 13, 148, 136), ('green', 22, 163, 74), ('lime', 101, 163, 13), ('amber', 217, 119, 6), ('orange', 234, 88, 12), ('red', 220, 38, 38), ('pink', 219, 39, 119), ('gray', 107, 114, 128)) AS h(hue, r, g, b) ORDER BY power((('x' || substr(n."color", 2, 2))::bit(8)::int - h.r), 2) + power((('x' || substr(n."color", 4, 2))::bit(8)::int - h.g), 2) + power((('x' || substr(n."color", 6, 2))::bit(8)::int - h.b), 2) LIMIT 1) WHERE n."slug" NOT IN ('lead', 'scheduled', 'assessed', 'quoted', 'accepted', 'in_progress', 'completed', 'deliverable_pending', 'deliverable_complete', 'invoiced', 'paid', 'on_hold', 'cancelled', 'draft', 'sent', 'rejected', 'expired', 'partial', 'voided', 'generating', 'ready', 'failed', 'queued', 'running', 'succeeded') AND n."color" ~ '^#[0-9A-Fa-f]{6}$';
